values
('bmlt-advanced-immunohematology-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',3101,$json${"question":"Which immunoglobulin class most commonly causes clinically significant warm autoimmune haemolytic anaemia?","translation":"","options":["IgG","IgM","IgA","IgE"],"correctIndex":0,"explanation":"Warm autoimmune haemolytic anaemia is most often mediated by IgG antibodies active at 37°C.","explanationNe":"Warm autoimmune haemolytic anaemia प्रायः ३७°C मा सक्रिय IgG antibody का कारण हुन्छ।","topic":"Warm autoantibodies"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',3102,$json${"question":"The direct antiglobulin test (DAT) detects:","translation":"","options":["Immunoglobulin and/or complement attached to red cells in vivo","Free antibody in patient serum only","ABO antigens in saliva","Platelet antibodies only"],"correctIndex":0,"explanation":"DAT detects IgG and/or complement coating red cells within the patient.","explanationNe":"DAT ले बिरामीको RBC मा शरीरभित्रै टाँसिएको IgG वा complement पत्ता लगाउँछ।","topic":"DAT"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3103,$json${"question":"The indirect antiglobulin test (IAT) is used to detect:","translation":"","options":["Free antibodies in serum or plasma that can bind red cells in vitro","Only complement already attached to patient RBCs","Haemoglobin concentration","Red cell count"],"correctIndex":0,"explanation":"IAT detects circulating antibodies by incubating patient serum with reagent red cells and using antiglobulin reagent.","explanationNe":"IAT ले serum/plasma मा रहेका RBC विरुद्धका antibody in vitro पत्ता लगाउँछ।","topic":"IAT"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',3104,$json${"question":"A positive DAT with IgG only may be seen in:","translation":"","options":["Warm autoimmune haemolytic anaemia","Iron deficiency anaemia","Thalassaemia trait only","Vitamin B12 deficiency only"],"correctIndex":0,"explanation":"IgG coating of red cells is characteristic of many warm autoimmune haemolytic cases.","explanationNe":"RBC मा IgG coating हुनु warm autoimmune haemolytic anaemia मा देखिन सक्छ।","topic":"DAT interpretation"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',3105,$json${"question":"A polyspecific AHG reagent commonly contains anti-IgG and:","translation":"","options":["Anti-C3d","Anti-A","Anti-B","Anti-D"],"correctIndex":0,"explanation":"Polyspecific antihuman globulin usually detects IgG and complement components such as C3d.","explanationNe":"Polyspecific AHG मा सामान्यतः anti-IgG र anti-C3d हुन्छ।","topic":"AHG reagents"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',3106,$json${"question":"The purpose of washing red cells before adding AHG reagent is to:","translation":"","options":["Remove unbound immunoglobulin that could neutralize AHG","Remove all red cell antigens","Increase haemoglobin concentration","Destroy complement on the cells"],"correctIndex":0,"explanation":"Adequate washing removes unbound globulins that could neutralize antiglobulin reagent and cause false-negative results.","explanationNe":"AHG थप्नुअघि washing गर्दा free globulin हट्छ र false-negative नतिजा रोकिन्छ।","topic":"AHG technique"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',3107,$json${"question":"Check cells (Coombs control cells) are added to a negative AHG test to:","translation":"","options":["Confirm that the AHG test was performed correctly","Determine the patient's ABO group","Measure serum bilirubin","Replace the positive control"],"correctIndex":0,"explanation":"Check cells should agglutinate in a valid negative AHG test, confirming active AHG reagent and adequate washing.","explanationNe":"Negative AHG test मा check cells agglutinate हुनुपर्छ, जसले परीक्षणको वैधता पुष्टि गर्छ।","topic":"AHG quality control"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',3108,$json${"question":"If check cells fail to agglutinate after a negative AHG test, the result is:","translation":"","options":["Invalid and must be repeated","Definitely compatible","A confirmed positive DAT","Suitable for immediate reporting"],"correctIndex":0,"explanation":"Failure of check cells to agglutinate means the negative AHG result is not validated.","explanationNe":"Check cells agglutinate नभए negative AHG result valid हुँदैन; परीक्षण दोहोर्‍याउनुपर्छ।","topic":"AHG quality control"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',3109,$json${"question":"The main purpose of an antibody screen before transfusion is to detect:","translation":"","options":["Unexpected clinically significant red cell antibodies","ABO antigens on donor platelets","Serum glucose","Bacterial contamination"],"correctIndex":0,"explanation":"Pretransfusion antibody screening identifies unexpected antibodies that may cause haemolytic reactions.","explanationNe":"Transfusion अघि antibody screen ले haemolytic reaction गराउन सक्ने unexpected antibody खोज्छ।","topic":"Antibody screening"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',3110,$json${"question":"A three-cell screening panel typically contains:","translation":"","options":["Three reagent red cell samples with defined antigen profiles","Three patient blood bags","Three different antisera only","Three platelet concentrates"],"correctIndex":0,"explanation":"Screening cells are selected reagent red cells with known antigen expression to detect unexpected antibodies.","explanationNe":"Screening panel मा antigen profile ज्ञात भएका reagent RBC प्रयोग गरिन्छ।","topic":"Antibody screening"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',3111,$json${"question":"An antibody identification panel is performed when:","translation":"","options":["The antibody screen is positive","The ABO group is O only","The haemoglobin is low","The crossmatch is always compatible"],"correctIndex":0,"explanation":"A positive screen is followed by an identification panel to determine antibody specificity.","explanationNe":"Antibody screen positive आएपछि कुन antibody हो भनेर identification panel गरिन्छ।","topic":"Antibody identification"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',3112,$json${"question":"The dosage effect in antibody identification means stronger reactions with cells that are:","translation":"","options":["Homozygous for the relevant antigen","Completely lacking the antigen","Always group O","Stored for more than 30 days"],"correctIndex":0,"explanation":"Some antibodies react more strongly with homozygous antigen-positive cells than heterozygous cells.","explanationNe":"Dosage effect मा homozygous antigen भएका RBC सँग reaction बढी बलियो हुन सक्छ।","topic":"Antibody identification"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',3113,$json${"question":"Which antibody is generally considered clinically significant because it can cause haemolytic disease of the fetus and newborn?","translation":"","options":["Anti-K","Anti-Lea","Anti-P1","Anti-M (cold-only)"],"correctIndex":0,"explanation":"Anti-K can cause severe fetal anaemia by suppressing erythropoiesis as well as haemolysis.","explanationNe":"Anti-K ले fetal RBC निर्माण दबाएर गम्भीर fetal anaemia गराउन सक्छ।","topic":"Clinical significance"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',3114,$json${"question":"Which blood group antibody is usually naturally occurring and predominantly IgM?","translation":"","options":["Anti-A and anti-B","Anti-D","Anti-K","Anti-c"],"correctIndex":0,"explanation":"ABO antibodies are commonly naturally occurring, predominantly IgM, though some IgG may occur.","explanationNe":"ABO antibody प्रायः naturally occurring र मुख्यतः IgM हुन्छ।","topic":"ABO antibodies"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',3115,$json${"question":"Anti-D is most commonly associated with which immunoglobulin class?","translation":"","options":["IgG","IgM only","IgE","IgA only"],"correctIndex":0,"explanation":"Anti-D is typically an immune IgG antibody and can cross the placenta.","explanationNe":"Anti-D सामान्यतः immune IgG हो र placenta पार गर्न सक्छ।","topic":"Rh antibodies"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',3116,$json${"question":"A weak D test is relevant when:","translation":"","options":["Initial D typing is weak or inconclusive under the applicable policy","ABO typing is missing","Serum is lipaemic","Platelet count is low"],"correctIndex":0,"explanation":"Weak D testing may clarify reduced D antigen expression; donor and recipient policies differ by setting.","explanationNe":"D typing कमजोर वा अस्पष्ट हुँदा लागू नीति अनुसार weak D परीक्षण गरिन्छ।","topic":"Rh typing"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',3117,$json${"question":"A major crossmatch tests:","translation":"","options":["Recipient serum/plasma against donor red cells","Donor serum against recipient platelets","Recipient urine against donor serum","Donor plasma against donor red cells"],"correctIndex":0,"explanation":"Major crossmatch detects recipient antibodies that may react with donor red cell antigens.","explanationNe":"Major crossmatch मा recipient serum/plasma लाई donor RBC सँग परीक्षण गरिन्छ।","topic":"Crossmatching"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',3118,$json${"question":"An electronic crossmatch may be used only when:","translation":"","options":["Validated computer rules and eligibility requirements are met","The patient has an unidentified antibody","ABO results are discrepant","The computer system is not validated"],"correctIndex":0,"explanation":"Electronic issue requires validated systems, reliable ABO records, and no relevant current or historical antibodies under policy.","explanationNe":"Electronic crossmatch का लागि validated system र निर्धारित eligibility पूरा हुनुपर्छ।","topic":"Crossmatching"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',3119,$json${"question":"A serological crossmatch is especially important when the patient has:","translation":"","options":["A clinically significant red cell antibody","Normal sodium","A negative urine glucose","A low platelet count alone"],"correctIndex":0,"explanation":"Patients with clinically significant antibodies require antigen-negative units and serological compatibility testing.","explanationNe":"Clinically significant antibody भएको बिरामीलाई antigen-negative र serologically compatible unit चाहिन्छ।","topic":"Crossmatching"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',3120,$json${"question":"The immediate-spin crossmatch primarily detects:","translation":"","options":["ABO incompatibility","All IgG antibodies optimally","HLA antibodies","Platelet antibodies"],"correctIndex":0,"explanation":"Immediate-spin testing is mainly designed to detect ABO incompatibility; it does not detect all clinically significant IgG antibodies.","explanationNe":"Immediate-spin crossmatch मुख्यतः ABO incompatibility पत्ता लगाउन उपयोगी हुन्छ।","topic":"Crossmatching"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',3121,$json${"question":"A delayed haemolytic transfusion reaction is commonly caused by:","translation":"","options":["An anamnestic response to a previously encountered red cell antigen","Contaminated saline only","Excessive platelet dose","Air embolism"],"correctIndex":0,"explanation":"A previously formed antibody may fall below detection and reappear after re-exposure, causing delayed haemolysis.","explanationNe":"पहिले बनेको antibody कम भएर नदेखिए पनि पुनः exposure पछि बढेर delayed haemolysis गराउन सक्छ।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',3122,$json${"question":"A common cause of acute intravascular haemolysis during transfusion is:","translation":"","options":["ABO-incompatible red cell transfusion","Mild allergic reaction","Febrile non-haemolytic reaction","Iron overload"],"correctIndex":0,"explanation":"ABO-incompatible transfusion can activate complement and cause rapid intravascular haemolysis.","explanationNe":"ABO नमिलेको RBC transfusion ले complement सक्रिय गरी तीव्र intravascular haemolysis गराउन सक्छ।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',3123,$json${"question":"The first action when a suspected acute transfusion reaction occurs is to:","translation":"","options":["Stop the transfusion immediately","Increase the transfusion rate","Discard the blood bag without investigation","Give another unit"],"correctIndex":0,"explanation":"Stop transfusion immediately, maintain IV access with appropriate saline, assess the patient, and notify the responsible team.","explanationNe":"Reaction शंका भए transfusion तुरुन्त रोक्ने, IV access कायम राख्ने र जिम्मेवार टोलीलाई खबर गर्ने।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',3124,$json${"question":"A febrile non-haemolytic transfusion reaction is commonly associated with:","translation":"","options":["Cytokines or recipient antibodies reacting with donor leukocytes","ABO mismatch in every case","Excess iron in the unit","Low donor platelet count"],"correctIndex":0,"explanation":"FNHTR is associated with cytokines in stored components or recipient antibodies against donor leukocytes.","explanationNe":"FNHTR cytokine वा donor leukocyte विरुद्ध recipient antibody का कारण हुन सक्छ।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',3125,$json${"question":"Which feature is more suggestive of an allergic transfusion reaction?","translation":"","options":["Urticaria and itching","Haemoglobinuria","Severe flank pain with shock","Marked plasma free haemoglobin"],"correctIndex":0,"explanation":"Mild allergic reactions commonly cause itching and urticaria; severe cases may involve anaphylaxis.","explanationNe":"Allergic transfusion reaction मा चिलाउने र urticaria देखिन सक्छ।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mock-001','BMLT','BMLT NHPC Licensing','mock','free',3126,$json${"question":"Transfusion-related acute lung injury (TRALI) typically presents with:","translation":"","options":["Acute hypoxaemia and bilateral pulmonary infiltrates during or within 6 hours of transfusion","Isolated jaundice after 2 weeks","Hypertension only after 1 month","Chronic iron overload"],"correctIndex":0,"explanation":"TRALI is acute non-cardiogenic pulmonary oedema with hypoxaemia, occurring during or within six hours of transfusion.","explanationNe":"TRALI मा transfusion को समयमा वा ६ घण्टाभित्र hypoxaemia र bilateral lung infiltrates देखिन्छ।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mock-002','BMLT','BMLT NHPC Licensing','mock','free',3127,$json${"question":"Transfusion-associated circulatory overload (TACO) is primarily due to:","translation":"","options":["Volume overload","Donor leukocyte antibodies only","Bacterial endotoxin only","ABO antibody"],"correctIndex":0,"explanation":"TACO is hydrostatic pulmonary oedema related to excessive or too rapid transfused volume.","explanationNe":"TACO transfused volume धेरै वा छिटो हुँदा हुने circulatory overload हो।","topic":"Transfusion reactions"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3128,$json${"question":"A clerical check during a transfusion reaction investigation includes verifying:","translation":"","options":["Patient identity and compatibility labels against the request and unit","Only the colour of the blood bag","Only the donor's age","The ward's room temperature"],"correctIndex":0,"explanation":"Clerical errors can cause fatal mismatched transfusions; identifiers and labels must be checked carefully.","explanationNe":"Clerical check मा बिरामीको पहिचान, request र blood unit का label मिलाइन्छ।","topic":"Reaction investigation"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mock-004','BMLT','BMLT NHPC Licensing','mock','free',3129,$json${"question":"A post-transfusion DAT may help investigate:","translation":"","options":["Immune coating of transfused or patient red cells","Serum sodium concentration","Platelet function","Blood culture contamination"],"correctIndex":0,"explanation":"DAT can demonstrate immunoglobulin or complement coating of red cells during an immune haemolytic reaction investigation.","explanationNe":"Transfusion reaction मा RBC मा antibody वा complement टाँसिएको छ कि छैन DAT ले देखाउन सक्छ।","topic":"Reaction investigation"}$json$::jsonb,true),
('bmlt-advanced-immunohematology-mock-005','BMLT','BMLT NHPC Licensing','mock','free',3130,$json${"question":"A clerical ABO mismatch with a positive crossmatch should prompt:","translation":"","options":["Immediate investigation and withholding of the incompatible unit","Issue the unit because the label is clear","Change the patient's blood group record without retesting","Ignore the result if the patient is stable"],"correctIndex":0,"explanation":"Any discrepancy or incompatible crossmatch must be resolved before issue except under authorized emergency-release procedures.","explanationNe":"ABO mismatch वा incompatible crossmatch भए कारण समाधान नभएसम्म unit दिनु हुँदैन।","topic":"Compatibility testing"}$json$::jsonb,true),
