('bmlt-advanced-immunohematology-mock-009','BMLT','BMLT NHPC Licensing','mock','free',3134,$json${"question":"A discrepancy between forward and reverse ABO grouping should be:","translation":"","options":["Resolved before routine blood component issue","Ignored if one test is clear","Reported as group AB automatically","Corrected by guessing age"],"correctIndex":0,"explanation":"ABO discrepancies require investigation and resolution before routine issue of ABO-specific components.","explanationNe":"Forward र reverse grouping नमिलेमा routine blood issue अघि discrepancy समाधान गर्नुपर्छ।","topic":"ABO discrepancies"}$json$::jsonb,true),
