('bmlt-advanced-immunohematology-mock-011','BMLT','BMLT NHPC Licensing','mock','free',3136,$json${"question":"A patient with Bombay phenotype generally requires red cells from:","translation":"","options":["Another Bombay phenotype donor","Any group O donor","Any Rh-negative donor","Any group AB donor"],"correctIndex":0,"explanation":"Because anti-H can react with ordinary donor cells, compatible Bombay phenotype units are needed.","explanationNe":"Anti-H ले सामान्य donor RBC सँग प्रतिक्रिया गर्न सक्छ, त्यसैले Bombay phenotype donor को रक्त चाहिन्छ।","topic":"Rare blood groups"}$json$::jsonb,true),
