('bmlt-advanced-immunohematology-mock-015','BMLT','BMLT NHPC Licensing','mock','free',3140,$json${"question":"The Lewis antibodies are commonly:","translation":"","options":["Naturally occurring and often IgM","Always IgG and strongly reactive at 37°C","Always clinically severe","Produced only after transfusion"],"correctIndex":0,"explanation":"Lewis antibodies are often naturally occurring IgM and are usually not clinically significant, though exceptions exist.","explanationNe":"Lewis antibody प्रायः naturally occurring IgM हुन्छ र धेरैजसो clinically significant हुँदैन।","topic":"Lewis system"}$json$::jsonb,true),
